const pptxgen = require("pptxgenjs");

// Sequoia-inspired color palette: dark navy primary, warm cream secondary, sharp coral accent
const COLORS = {
  navy: "1E2761",
  iceBlue: "CADCFC",
  white: "FFFFFF",
  coral: "F96167",
  gold: "F9E795",
  darkNavy: "0F1535",
  lightGray: "F5F7FA",
  midGray: "8A94A6",
  textDark: "1E293B",
  textMuted: "64748B",
  incumbent: "1E2761",
  aiFirst: "F96167",
};

let pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Sequoia Capital";
pres.title = "Generative AI's Act Two: From Technology Hammer to Real Value";
pres.subject = "Generative AI Market Analysis";

// Define a slide master for content slides
pres.defineSlideMaster({
  title: "MASTER_CONTENT",
  background: { color: COLORS.white },
  objects: [],
});

// ==========================================
// SLIDE 1: Title Slide
// ==========================================
let slide1 = pres.addSlide();
slide1.background = { color: COLORS.darkNavy };

// Subtle top accent bar
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.08,
  fill: { color: COLORS.coral },
});

// Title
slide1.addText("Generative AI's Act Two", {
  x: 0.8, y: 1.6, w: 8.4, h: 1.0,
  fontSize: 44, fontFace: "Georgia", bold: true,
  color: COLORS.white, align: "left", valign: "middle",
  margin: 0,
});

// Subtitle
slide1.addText("From Technology Hammer to Real Value", {
  x: 0.8, y: 2.5, w: 8.4, h: 0.6,
  fontSize: 24, fontFace: "Calibri", italic: true,
  color: COLORS.iceBlue, align: "left", valign: "middle",
  margin: 0,
});

// Attribution
slide1.addText("Sequoia Capital  |  September 2023", {
  x: 0.8, y: 4.2, w: 8.4, h: 0.4,
  fontSize: 14, fontFace: "Calibri",
  color: COLORS.midGray, align: "left", valign: "middle",
  margin: 0,
});

// Decorative accent line
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0.8, y: 2.35, w: 1.5, h: 0.03,
  fill: { color: COLORS.coral },
});

// ==========================================
// SLIDE 2: Decades of Convergence
// ==========================================
let slide2 = pres.addSlide();
slide2.background = { color: COLORS.white };

// Title
slide2.addText("Six Decades of Technological Progress Converged to Enable Generative AI", {
  x: 0.5, y: 0.35, w: 9.0, h: 0.9,
  fontSize: 28, fontFace: "Georgia", bold: true,
  color: COLORS.navy, align: "left", valign: "top",
  margin: 0,
});

// Timeline blocks
const timelineY = 1.6;
const blockH = 2.6;
const blockW = 2.7;
const gap = 0.35;
const startX = 0.5;

// Block 1: Moore's Law
slide2.addShape(pres.shapes.RECTANGLE, {
  x: startX, y: timelineY, w: blockW, h: blockH,
  fill: { color: COLORS.navy },
});
slide2.addText("6 Decades", {
  x: startX, y: timelineY + 0.2, w: blockW, h: 0.5,
  fontSize: 32, fontFace: "Georgia", bold: true,
  color: COLORS.white, align: "center", valign: "middle",
  margin: 0,
});
slide2.addText("Moore's Law", {
  x: startX, y: timelineY + 0.75, w: blockW, h: 0.4,
  fontSize: 16, fontFace: "Calibri", bold: true,
  color: COLORS.gold, align: "center", valign: "middle",
  margin: 0,
});
slide2.addText("Compute horsepower to process exaflops of data", {
  x: startX + 0.15, y: timelineY + 1.2, w: blockW - 0.3, h: 0.8,
  fontSize: 13, fontFace: "Calibri",
  color: COLORS.iceBlue, align: "center", valign: "top",
  margin: 0,
});

// Block 2: Internet
slide2.addShape(pres.shapes.RECTANGLE, {
  x: startX + blockW + gap, y: timelineY, w: blockW, h: blockH,
  fill: { color: COLORS.navy },
});
slide2.addText("4 Decades", {
  x: startX + blockW + gap, y: timelineY + 0.2, w: blockW, h: 0.5,
  fontSize: 32, fontFace: "Georgia", bold: true,
  color: COLORS.white, align: "center", valign: "middle",
  margin: 0,
});
slide2.addText("The Internet", {
  x: startX + blockW + gap, y: timelineY + 0.75, w: blockW, h: 0.4,
  fontSize: 16, fontFace: "Calibri", bold: true,
  color: COLORS.gold, align: "center", valign: "middle",
  margin: 0,
});
slide2.addText("Trillions of tokens of training data (accelerated by COVID)", {
  x: startX + blockW + gap + 0.15, y: timelineY + 1.2, w: blockW - 0.3, h: 0.8,
  fontSize: 13, fontFace: "Calibri",
  color: COLORS.iceBlue, align: "center", valign: "top",
  margin: 0,
});

// Block 3: Mobile/Cloud
slide2.addShape(pres.shapes.RECTANGLE, {
  x: startX + 2 * (blockW + gap), y: timelineY, w: blockW, h: blockH,
  fill: { color: COLORS.navy },
});
slide2.addText("2 Decades", {
  x: startX + 2 * (blockW + gap), y: timelineY + 0.2, w: blockW, h: 0.5,
  fontSize: 32, fontFace: "Georgia", bold: true,
  color: COLORS.white, align: "center", valign: "middle",
  margin: 0,
});
slide2.addText("Mobile & Cloud", {
  x: startX + 2 * (blockW + gap), y: timelineY + 0.75, w: blockW, h: 0.4,
  fontSize: 16, fontFace: "Calibri", bold: true,
  color: COLORS.gold, align: "center", valign: "middle",
  margin: 0,
});
slide2.addText("A supercomputer in every human's palm", {
  x: startX + 2 * (blockW + gap) + 0.15, y: timelineY + 1.2, w: blockW - 0.3, h: 0.8,
  fontSize: 13, fontFace: "Calibri",
  color: COLORS.iceBlue, align: "center", valign: "top",
  margin: 0,
});

// Bottom context text
slide2.addText("ChatGPT's launch ignited a Cambrian explosion of innovation not seen since the early internet — but cracks quickly appeared as products fell short of expectations.", {
  x: 0.5, y: 4.5, w: 9.0, h: 0.7,
  fontSize: 14, fontFace: "Calibri", italic: true,
  color: COLORS.textMuted, align: "left", valign: "top",
  margin: 0,
});

// ==========================================
// SLIDE 3: GenAI Outpaces SaaS
// ==========================================
let slide3 = pres.addSlide();
slide3.background = { color: COLORS.white };

// Title
slide3.addText("GenAI Startups Surpassed $1B Revenue Faster Than SaaS Ever Did", {
  x: 0.5, y: 0.35, w: 9.0, h: 0.9,
  fontSize: 28, fontFace: "Georgia", bold: true,
  color: COLORS.navy, align: "left", valign: "top",
  margin: 0,
});

// Big stat callout
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.4, w: 4.2, h: 1.6,
  fill: { color: COLORS.lightGray },
});
slide3.addText(">$1B", {
  x: 0.5, y: 1.5, w: 4.2, h: 0.8,
  fontSize: 56, fontFace: "Georgia", bold: true,
  color: COLORS.coral, align: "center", valign: "middle",
  margin: 0,
});
slide3.addText("Startup revenue in months, not years", {
  x: 0.5, y: 2.3, w: 4.2, h: 0.5,
  fontSize: 14, fontFace: "Calibri",
  color: COLORS.textMuted, align: "center", valign: "middle",
  margin: 0,
});

// Standout examples - card 1
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 5.0, y: 1.4, w: 4.5, h: 0.75,
  fill: { color: COLORS.navy },
});
slide3.addText("ChatGPT", {
  x: 5.15, y: 1.45, w: 2.0, h: 0.35,
  fontSize: 16, fontFace: "Calibri", bold: true,
  color: COLORS.gold, align: "left", valign: "middle",
  margin: 0,
});
slide3.addText("Fastest-growing application in history", {
  x: 5.15, y: 1.75, w: 4.2, h: 0.3,
  fontSize: 12, fontFace: "Calibri",
  color: COLORS.iceBlue, align: "left", valign: "middle",
  margin: 0,
});

// Card 2
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 5.0, y: 2.3, w: 4.5, h: 0.75,
  fill: { color: COLORS.navy },
});
slide3.addText("Midjourney", {
  x: 5.15, y: 2.35, w: 2.0, h: 0.35,
  fontSize: 16, fontFace: "Calibri", bold: true,
  color: COLORS.gold, align: "left", valign: "middle",
  margin: 0,
});
slide3.addText("Hundreds of millions in revenue with just 11 people", {
  x: 5.15, y: 2.65, w: 4.2, h: 0.3,
  fontSize: 12, fontFace: "Calibri",
  color: COLORS.iceBlue, align: "left", valign: "middle",
  margin: 0,
});

// Card 3
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 5.0, y: 3.2, w: 4.5, h: 0.75,
  fill: { color: COLORS.navy },
});
slide3.addText("Character.ai", {
  x: 5.15, y: 3.25, w: 2.0, h: 0.35,
  fontSize: 16, fontFace: "Calibri", bold: true,
  color: COLORS.gold, align: "left", valign: "middle",
  margin: 0,
});
slide3.addText("Users spend an average of 2 hours per session", {
  x: 5.15, y: 3.55, w: 4.2, h: 0.3,
  fontSize: 12, fontFace: "Calibri",
  color: COLORS.iceBlue, align: "left", valign: "middle",
  margin: 0,
});

// Bottom caveat
slide3.addText("Despite rapid revenue growth, many AI companies still lack product-market fit or sustainable competitive advantage.", {
  x: 0.5, y: 4.5, w: 9.0, h: 0.5,
  fontSize: 14, fontFace: "Calibri", italic: true,
  color: COLORS.textMuted, align: "left", valign: "top",
  margin: 0,
});

// ==========================================
// SLIDE 4: Retention Gap (Bar Chart)
// ==========================================
let slide4 = pres.addSlide();
slide4.background = { color: COLORS.white };

// Title
slide4.addText("AI-First Apps Show 14% Median Retention vs. 51% for Incumbents", {
  x: 0.5, y: 0.3, w: 9.0, h: 0.8,
  fontSize: 26, fontFace: "Georgia", bold: true,
  color: COLORS.navy, align: "left", valign: "top",
  margin: 0,
});

// Chart data
const incumbentLabels = ["WhatsApp", "Instagram", "YouTube", "TikTok", "Snapchat", "Roblox", "Tinder", "Candy Crush", "Duolingo"];
const incumbentValues = [85, 64, 64, 60, 51, 41, 34, 32, 30];
const aiLabels = ["Character.ai", "Runway", "Remini", "ChatGPT", "Lensa"];
const aiValues = [41, 27, 14, 14, 12];

// Incumbent chart
slide4.addChart(pres.charts.BAR, [{
  name: "Retention %",
  labels: incumbentLabels,
  values: incumbentValues,
}], {
  x: 0.4, y: 1.2, w: 4.5, h: 3.6,
  barDir: "col",
  barGrouping: "clustered",
  chartColors: [COLORS.incumbent],
  chartArea: { fill: { color: COLORS.white }, roundedCorners: false },
  catAxisLabelColor: COLORS.textMuted,
  valAxisLabelColor: COLORS.textMuted,
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: COLORS.textDark,
  dataLabelFontSize: 10,
  showLegend: false,
  showTitle: true,
  title: "Incumbents (Median: 51%)",
  titleFontSize: 13,
  titleColor: COLORS.navy,
  titleBold: true,
  valAxisMaxVal: 100,
  valAxisMinVal: 0,
  catAxisLabelFontSize: 10,
  valAxisLabelFontSize: 10,
});

// AI-First chart
slide4.addChart(pres.charts.BAR, [{
  name: "Retention %",
  labels: aiLabels,
  values: aiValues,
}], {
  x: 5.1, y: 1.2, w: 4.5, h: 3.6,
  barDir: "col",
  barGrouping: "clustered",
  chartColors: [COLORS.aiFirst],
  chartArea: { fill: { color: COLORS.white }, roundedCorners: false },
  catAxisLabelColor: COLORS.textMuted,
  valAxisLabelColor: COLORS.textMuted,
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: COLORS.textDark,
  dataLabelFontSize: 10,
  showLegend: false,
  showTitle: true,
  title: "AI-First Companies (Median: 14%)",
  titleFontSize: 13,
  titleColor: COLORS.coral,
  titleBold: true,
  valAxisMaxVal: 100,
  valAxisMinVal: 0,
  catAxisLabelFontSize: 10,
  valAxisLabelFontSize: 10,
});

// Bottom stat callout
slide4.addShape(pres.shapes.RECTANGLE, {
  x: 0.4, y: 4.95, w: 9.2, h: 0.45,
  fill: { color: COLORS.lightGray },
});
slide4.addText("3.6x retention disadvantage for AI-first apps", {
  x: 0.4, y: 4.95, w: 9.2, h: 0.45,
  fontSize: 14, fontFace: "Calibri", bold: true,
  color: COLORS.coral, align: "center", valign: "middle",
  margin: 0,
});

// ==========================================
// SLIDE 5: Incumbent Monthly Usage
// ==========================================
let slide5 = pres.addSlide();
slide5.background = { color: COLORS.white };

// Title
slide5.addText("YouTube Leads Incumbents at 85% Monthly Active Usage", {
  x: 0.5, y: 0.35, w: 9.0, h: 0.8,
  fontSize: 28, fontFace: "Georgia", bold: true,
  color: COLORS.navy, align: "left", valign: "top",
  margin: 0,
});

// Chart
const mauLabels = ["YouTube", "Instagram", "TikTok", "Snapchat", "WhatsApp", "Roblox", "Tinder", "Duolingo", "Candy Crush"];
const mauValues = [85, 73, 69, 67, 63, 61, 54, 50, 48];

slide5.addChart(pres.charts.BAR, [{
  name: "Monthly Active Usage %",
  labels: mauLabels,
  values: mauValues,
}], {
  x: 0.5, y: 1.3, w: 9.0, h: 3.5,
  barDir: "bar",
  barGrouping: "clustered",
  chartColors: [COLORS.incumbent],
  chartArea: { fill: { color: COLORS.white }, roundedCorners: false },
  catAxisLabelColor: COLORS.textMuted,
  valAxisLabelColor: COLORS.textMuted,
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: COLORS.textDark,
  dataLabelFontSize: 11,
  showLegend: false,
  showTitle: false,
  valAxisMaxVal: 100,
  valAxisMinVal: 0,
  catAxisLabelFontSize: 11,
  valAxisLabelFontSize: 11,
});

// Median callout
slide5.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 4.95, w: 9.0, h: 0.45,
  fill: { color: COLORS.lightGray },
});
slide5.addText("Incumbent Median: 63% Monthly Active Usage  —  the bar AI apps must clear", {
  x: 0.5, y: 4.95, w: 9.0, h: 0.45,
  fontSize: 14, fontFace: "Calibri", bold: true,
  color: COLORS.navy, align: "center", valign: "middle",
  margin: 0,
});

// ==========================================
// SLIDE 6: Act 1 vs Act 2
// ==========================================
let slide6 = pres.addSlide();
slide6.background = { color: COLORS.white };

// Title
slide6.addText("Act 1 Was Technology-Out; Act 2 Is Customer-Back", {
  x: 0.5, y: 0.35, w: 9.0, h: 0.8,
  fontSize: 28, fontFace: "Georgia", bold: true,
  color: COLORS.navy, align: "left", valign: "top",
  margin: 0,
});

// Left column header: Act 1
slide6.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.2, w: 4.3, h: 0.55,
  fill: { color: COLORS.midGray },
});
slide6.addText("Act 1: Technology-Out", {
  x: 0.5, y: 1.2, w: 4.3, h: 0.55,
  fontSize: 18, fontFace: "Calibri", bold: true,
  color: COLORS.white, align: "center", valign: "middle",
  margin: 0,
});

// Left column body
slide6.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.75, w: 4.3, h: 3.3,
  fill: { color: COLORS.lightGray },
});

const act1Items = [
  "Foundation models as the entire solution",
  "Novelty demos and lightweight wrappers",
  "Poor user retention and stickiness",
  "Cool technology searching for problems",
  "Thin layer over a foundation model API",
];

let act1Y = 1.9;
act1Items.forEach((item) => {
  slide6.addText(item, {
    x: 0.7, y: act1Y, w: 3.9, h: 0.55,
    fontSize: 14, fontFace: "Calibri",
    color: COLORS.textDark, align: "left", valign: "top",
    bullet: true, margin: 0,
  });
  act1Y += 0.58;
});

// Right column header: Act 2
slide6.addShape(pres.shapes.RECTANGLE, {
  x: 5.2, y: 1.2, w: 4.3, h: 0.55,
  fill: { color: COLORS.coral },
});
slide6.addText("Act 2: Customer-Back", {
  x: 5.2, y: 1.2, w: 4.3, h: 0.55,
  fontSize: 18, fontFace: "Calibri", bold: true,
  color: COLORS.white, align: "center", valign: "middle",
  margin: 0,
});

// Right column body
slide6.addShape(pres.shapes.RECTANGLE, {
  x: 5.2, y: 1.75, w: 4.3, h: 3.3,
  fill: { color: COLORS.lightGray },
});

const act2Items = [
  "Foundation models as a piece of the solution",
  "New editing interfaces for stickier workflows",
  "Multi-modal, end-to-end problem solving",
  "Solving human problems comprehensively",
  "Deep workflow integration and value delivery",
];

let act2Y = 1.9;
act2Items.forEach((item) => {
  slide6.addText(item, {
    x: 5.4, y: act2Y, w: 3.9, h: 0.55,
    fontSize: 14, fontFace: "Calibri",
    color: COLORS.textDark, align: "left", valign: "top",
    bullet: true, margin: 0,
  });
  act2Y += 0.58;
});

// Exemplars footer
slide6.addText("Act 2 Exemplars: Harvey (legal), Glean (enterprise search), Character & Ava (companionship)", {
  x: 0.5, y: 5.15, w: 9.0, h: 0.35,
  fontSize: 12, fontFace: "Calibri", italic: true,
  color: COLORS.textMuted, align: "center", valign: "middle",
  margin: 0,
});

// ==========================================
// SLIDE 7: Market Map Evolution
// ==========================================
let slide7 = pres.addSlide();
slide7.background = { color: COLORS.white };

// Title
slide7.addText("Market Map Reorganized by Use Case, Not Model Modality", {
  x: 0.5, y: 0.35, w: 9.0, h: 0.8,
  fontSize: 28, fontFace: "Georgia", bold: true,
  color: COLORS.navy, align: "left", valign: "top",
  margin: 0,
});

// Before / After visual
// Before box
slide7.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.4, w: 4.0, h: 2.8,
  fill: { color: COLORS.lightGray },
});
slide7.addText("BEFORE", {
  x: 0.5, y: 1.5, w: 4.0, h: 0.4,
  fontSize: 14, fontFace: "Calibri", bold: true,
  color: COLORS.midGray, align: "center", valign: "middle",
  margin: 0,
});
slide7.addText("Organized by Model Modality", {
  x: 0.5, y: 1.9, w: 4.0, h: 0.4,
  fontSize: 16, fontFace: "Calibri", bold: true,
  color: COLORS.textDark, align: "center", valign: "middle",
  margin: 0,
});

const beforeItems = ["Text models", "Image models", "Code models", "Audio models"];
let beforeY = 2.4;
beforeItems.forEach((item) => {
  slide7.addText(item, {
    x: 0.7, y: beforeY, w: 3.6, h: 0.4,
    fontSize: 13, fontFace: "Calibri",
    color: COLORS.textMuted, align: "center", valign: "middle",
    margin: 0,
  });
  beforeY += 0.45;
});

// Arrow
slide7.addShape(pres.shapes.LINE, {
  x: 4.6, y: 2.8, w: 0.8, h: 0,
  line: { color: COLORS.coral, width: 3 },
});
slide7.addShape(pres.shapes.LINE, {
  x: 5.2, y: 2.6, w: 0.2, h: 0.2,
  line: { color: COLORS.coral, width: 3 },
});

// After box
slide7.addShape(pres.shapes.RECTANGLE, {
  x: 5.5, y: 1.4, w: 4.0, h: 2.8,
  fill: { color: COLORS.navy },
});
slide7.addText("AFTER", {
  x: 5.5, y: 1.5, w: 4.0, h: 0.4,
  fontSize: 14, fontFace: "Calibri", bold: true,
  color: COLORS.gold, align: "center", valign: "middle",
  margin: 0,
});
slide7.addText("Organized by Use Case", {
  x: 5.5, y: 1.9, w: 4.0, h: 0.4,
  fontSize: 16, fontFace: "Calibri", bold: true,
  color: COLORS.white, align: "center", valign: "middle",
  margin: 0,
});

const afterItems = ["Legal (Harvey)", "Enterprise Search (Glean)", "Companionship (Character, Ava)", "Multi-modal workflows"];
let afterY = 2.4;
afterItems.forEach((item) => {
  slide7.addText(item, {
    x: 5.7, y: afterY, w: 3.6, h: 0.4,
    fontSize: 13, fontFace: "Calibri",
    color: COLORS.iceBlue, align: "center", valign: "middle",
    margin: 0,
  });
  afterY += 0.45;
});

// Bottom text
slide7.addText("This reorganization mirrors the broader Act 1 to Act 2 transition — from technology hammer to actual value delivery.", {
  x: 0.5, y: 4.5, w: 9.0, h: 0.6,
  fontSize: 14, fontFace: "Calibri", italic: true,
  color: COLORS.textMuted, align: "left", valign: "top",
  margin: 0,
});

// ==========================================
// SLIDE 8: Key Takeaways
// ==========================================
let slide8 = pres.addSlide();
slide8.background = { color: COLORS.darkNavy };

// Top accent
slide8.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.08,
  fill: { color: COLORS.coral },
});

// Title
slide8.addText("Key Takeaways: What Separates Winners in Act Two", {
  x: 0.6, y: 0.4, w: 8.8, h: 0.7,
  fontSize: 30, fontFace: "Georgia", bold: true,
  color: COLORS.white, align: "left", valign: "middle",
  margin: 0,
});

// 5 takeaway cards
const takeaways = [
  { num: "01", text: "Retention is the critical challenge — AI-first apps at 14% median vs. 51% for incumbents" },
  { num: "02", text: "Foundation models should be a component, not the whole product" },
  { num: "03", text: "Multi-modal, workflow-integrated solutions will win" },
  { num: "04", text: "The $1B+ revenue milestone proves real demand exists despite hype cycles" },
  { num: "05", text: "Companies solving end-to-end human problems will define Act 2" },
];

let cardY = 1.25;
const cardH = 0.72;
const cardGap = 0.12;

